import random, itertools, time
n=17
all_edges=[(i,j) for i in range(n) for j in range(i+1,n)]
adj=[0]*n
def girth_ok(edges):
 adj=[set() for _ in range(n)]
 for u,v in edges:
  adj[u].add(v); adj[v].add(u)
 # for each edge, shortest path between u,v without edge length <=5 gives cycle <=6; also triangle...
 for u,v in edges:
  # bfs depth 5 from u to v excluding edge
  seen={u}; frontier=[u]
  for d in range(1,6):
   nf=[]
   for x in frontier:
    for y in adj[x]:
     if (x==u and y==v) or (x==v and y==u): continue
     if y==v:
      return False
     if y not in seen:
      seen.add(y); nf.append(y)
   frontier=nf
 return True

def three_col(edges):
 adj=[[] for _ in range(n)]
 for u,v in edges: adj[u].append(v); adj[v].append(u)
 order=sorted(range(n), key=lambda x: -len(adj[x]))
 col=[-1]*n
 def bt(k):
  if k==n: return True
  v=order[k]
  used={col[w] for w in adj[v] if col[w]>=0}
  for c in range(3):
   if c not in used:
    col[v]=c
    if bt(k+1): return True
    col[v]=-1
  return False
 return bt(0), col

def can_add(edges, edge):
 # edge ok if no path length <=5 between endpoints in existing graph
 adj=[[] for _ in range(n)]
 for u,v in edges:
  adj[u].append(v); adj[v].append(u)
 u,v=edge
 seen={u}; frontier=[u]
 for d in range(1,6):
  nf=[]
  for x in frontier:
   for y in adj[x]:
    if y==v: return False
    if y not in seen:
     seen.add(y); nf.append(y)
  frontier=nf
 return True

